<?php require_once __DIR__.'/config.php';$u=require_login();if($_SERVER['REQUEST_METHOD']!=='POST')redirect('index.php');check_csrf();$type=$_POST['type']??'thread';$id=(int)($_POST['id']??0);$file=$type==='reply'?'likes_reply_'.$id.'.json':'likes_thread_'.$id.'.json';$likes=data_load($file);$uid=(int)$u['id'];$found=array_search($uid,array_map('intval',$likes),true);if($found===false)$likes[]=$uid;else unset($likes[$found]);$likes=array_values(array_unique(array_map('intval',$likes)));data_save($file,$likes);$back=$_SERVER['HTTP_REFERER']??'index.php';redirect($back);